const e=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export const DESMOS_URL='https://www.desmos.com/testing/cb-digital-sat/graphing';
export function toolkit(q,p,state){return `<div class="exam-toolbar" role="group" aria-label="Practice tools">${q.subject==='Math'?'<button data-action="calculator">▦ Desmos</button><button data-action="reference">ƒ Reference</button>':'<button data-action="highlight">▰ Highlight selection</button><button data-action="clear-highlights">Clear highlights</button>'}<button data-action="eliminator" aria-pressed="${!!p.eliminateMode}" class="${p.eliminateMode?'active':''}">⊘ Eliminate</button><button data-action="mark-review" aria-pressed="${state.markedForReview?.includes(q.id)||false}" class="${state.markedForReview?.includes(q.id)?'active':''}">⚑ Mark for review</button></div>`;}
export function calculatorHTML(online=true){return `<div class="calculator-top-note"><span>${online?'Desmos testing graphing calculator · internet required':'You appear offline. Desmos needs internet; the basic calculator below works locally.'}</span><a href="${DESMOS_URL}" target="_blank" rel="noopener noreferrer">Open the full SAT-style calculator ↗</a></div><iframe class="desmos-frame" title="Desmos SAT testing graphing calculator" src="${DESMOS_URL}" referrerpolicy="no-referrer" allow="fullscreen"></iframe><form id="basic-calculator" class="basic-calculator"><label>Offline arithmetic backup<input name="expression" placeholder="e.g. sqrt(25) + 3^2" aria-label="Arithmetic expression" autocomplete="off"></label><button class="button secondary">Calculate</button><output id="calculator-output" aria-live="polite"></output></form>`;}
export function referenceHTML(){return `<div class="reference-sheet"><span class="eyebrow">MATH QUICK REFERENCE</span><h3>Shapes, distances, and quantities.</h3><div><p><b>Circle</b>A = πr²<br>C = 2πr</p><p><b>Rectangle</b>A = lw</p><p><b>Triangle</b>A = ½bh<br>a² + b² = c² for a right triangle</p><p><b>Special right triangles</b>45–45–90: x, x, x√2<br>30–60–90: x, x√3, 2x</p><p><b>Solid volumes</b>Box: lwh<br>Cylinder: πr²h<br>Sphere: ⁴⁄₃πr³<br>Cone: ⅓πr²h<br>Pyramid: ⅓lwh</p><p><b>Angles</b>A triangle: 180°<br>A full circle: 360° = 2π radians</p></div><p>Original practice reference, not the official Bluebook interface. Open the full rules and tips library from the sidebar.</p></div>`;}
export function highlightedPassage(text,ranges=[]){const valid=ranges.filter(r=>Array.isArray(r)&&r.length===2&&Number.isInteger(r[0])&&Number.isInteger(r[1])&&r[0]>=0&&r[1]<=text.length&&r[0]<r[1]).sort((a,b)=>a[0]-b[0]);const merged=[];for(const r of valid){if(merged.length&&r[0]<=merged.at(-1)[1])merged.at(-1)[1]=Math.max(merged.at(-1)[1],r[1]);else merged.push([...r]);}let at=0,html='';for(const [start,end]of merged){html+=e(text.slice(at,start))+`<mark>${e(text.slice(start,end))}</mark>`;at=end;}return html+e(text.slice(at));}
// Restricted arithmetic parser: numbers, parentheses, + − × ÷ ^, sqrt(), and pi. No eval.
export function calculate(source){const input=String(source).replace(/π/g,'pi').replace(/×/g,'*').replace(/÷/g,'/').replace(/−/g,'-').replace(/\s+/g,'');if(input.length>160)throw Error('Use a shorter expression.');const tokens=input.match(/sqrt|pi|\d*\.?\d+|[()+\-*/^]/g)||[];if(tokens.join('')!==input)throw Error('Use numbers, + − × ÷ ^, sqrt(), and pi.');let i=0;function atom(){const t=tokens[i++];if(t==='('){const n=expr();if(tokens[i++]!==')')throw Error('Check parentheses.');return n;}if(t==='sqrt'){if(tokens[i++]!=='(')throw Error('Use sqrt(number).');const n=expr();if(tokens[i++]!==')'||n<0)throw Error('Check the square root.');return Math.sqrt(n);}if(t==='pi')return Math.PI;if(t!==undefined&&/^\d*\.?\d+$/.test(t))return Number(t);throw Error('Check the expression.');}function power(){let n=atom();if(tokens[i]==='^'){i++;n=n**unary();}return n;}function unary(){if(tokens[i]==='-'){i++;return-unary();}if(tokens[i]==='+'){i++;return unary();}return power();}function term(){let n=unary();while(tokens[i]==='*'||tokens[i]==='/'){const op=tokens[i++],v=unary();n=op==='*'?n*v:n/v;}return n;}function expr(){let n=term();while(tokens[i]==='+'||tokens[i]==='-'){const op=tokens[i++],v=term();n=op==='+'?n+v:n-v;}return n;}const value=expr();if(i!==tokens.length||!Number.isFinite(value))throw Error('The expression has no finite real result.');return Number(value.toPrecision(12));}
